X=D['X'].astype(np.float32); y=D['y']; Xt=V['X'].astype(np.float32); yt=V['y']

def acc(p): return (p==yt).mean()
def standard(X):
 mu=X.mean(0); sd=X.std(0)+1e-6; return (X-mu)/sd,mu,sd
Xs,mu,sd=standard(X); Vs=(Xt-mu)/sd
print('priors',np.bincount(y,minlength=10)/len(y),np.bincount(yt,minlength=10)/len(yt))
# simple centroid, diagonal gaussian, full LDA/QDA
for name, func in []: pass
for typ in ['centroid','diag','lda','qda']:
 means=np.array([Xs[y==c].mean(0) for c in range(10)])
 if typ=='centroid':
  score=-((Vs[:,None,:]-means[None,:,:])**2).sum(2)
 elif typ=='diag':
  var=np.array([Xs[y==c].var(0)+.1 for c in range(10)])
  score=-.5*(((Vs[:,None,:]-means[None,:,:])**2)/var[None,:,:]+np.log(var[None,:,:])).sum(2)
 else:
